"use client";

import * as React from "react";
import { AlertCircle, ChevronDown, FileCode2, RotateCcw } from "lucide-react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * TASK LOG: what the agent did, task by task, as it does it
 *
 *   running   the task's title carries a sweep of light; its
 *             steps arrive one at a time on a thin line trail,
 *             each opening to its height and rising out of a
 *             light blur, the newest one shimmering
 *   done      the title morphs into the past tense ("Finding
 *             project files" becomes "Found project files") and
 *             the sweep stops; the steps can fold away
 *   error     the title turns red behind an alert, keeping the
 *             steps that ran
 *   rerun     once every task is settled, "Run again" folds in
 *
 * Files in a step sit in small chips; counts and outcomes trail
 * after in a quieter grey. Feed it the tasks you have so far.
 * ───────────────────────────────────────────────────────── */

export type TaskLogStatus = "running" | "done" | "error";

export interface TaskLogStep {
  id: string;
  /** What happened, e.g. "Read" or "Searching \"app/page.tsx\"". */
  text: string;
  /** A file it touched, shown as a chip after the text. */
  file?: string;
  /** A quieter outcome after it, e.g. "0 errors". */
  detail?: string;
}

export interface TaskLogTask {
  id: string;
  /** While it runs, e.g. "Finding project files". */
  title: string;
  /** Once it's done, e.g. "Found project files". Defaults to title. */
  doneTitle?: string;
  icon?: React.ReactNode;
  status: TaskLogStatus;
  steps: TaskLogStep[];
}

export interface TaskLogProps extends React.HTMLAttributes<HTMLDivElement> {
  tasks: TaskLogTask[];
  /** Shows "Run again" once every task is settled. */
  onRerun?: () => void;
  rerunLabel?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
// A light that sweeps across the label: a moving mask, so it also reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none]";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Opens to its height and rises out of a blur the first time it appears (not when the log first renders). */
function Arrive({
  animate,
  reduced,
  children,
}: {
  animate: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [shown, setShown] = React.useState(!animate || reduced);
  React.useEffect(() => {
    if (shown) return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setShown(true))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [shown]);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: shown ? "1fr" : "0fr",
        opacity: shown ? 1 : 0,
        filter: shown ? "none" : "blur(4px)",
        transform: shown ? "none" : "translateY(4px)",
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${EASE}, opacity 320ms ${EASE} 60ms, filter 320ms ${EASE} 60ms, transform 380ms ${EASE}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">{children}</div>
    </div>
  );
}

function FileChip({ name }: { name: string }) {
  return (
    <span className="inline-flex h-5 max-w-full items-center gap-1 rounded-md bg-muted px-1.5 font-mono text-[11px] text-foreground/80">
      <FileCode2
        aria-hidden="true"
        className="size-3 shrink-0 text-muted-foreground"
      />
      <span className="truncate">{name}</span>
    </span>
  );
}

function Task({
  task,
  animate,
  mounted,
  reduced,
}: {
  task: TaskLogTask;
  animate: boolean;
  mounted: boolean;
  reduced: boolean;
}) {
  const [open, setOpen] = React.useState(true);
  const listId = React.useId();
  const running = task.status === "running";
  const failed = task.status === "error";
  const title = running ? task.title : (task.doneTitle ?? task.title);
  return (
    <li>
      <Arrive animate={animate} reduced={reduced}>
        <button
          type="button"
          aria-expanded={open}
          aria-controls={listId}
          onClick={() => setOpen((o) => !o)}
          className={`cursor-pointer group flex min-h-7 w-full items-center gap-2 rounded-md py-0.5 text-left text-[13px] ${FOCUS}`}
        >
          <span
            aria-hidden="true"
            className={`flex size-4 shrink-0 items-center justify-center [&_svg]:size-4 [&_svg]:stroke-[1.8] ${failed ? "text-red-500" : "text-muted-foreground"}`}
          >
            {failed ? <AlertCircle /> : task.icon}
          </span>
          <span
            className={`min-w-0 font-medium transition-colors duration-300 ${failed ? "text-red-600 dark:text-red-400" : running ? SHEEN : "text-foreground/80"}`}
          >
            <TextMorph>{title}</TextMorph>
          </span>
          <ChevronDown
            aria-hidden="true"
            className="ml-auto size-3.5 shrink-0 text-muted-foreground opacity-60 transition-opacity group-hover:opacity-100"
            style={{
              transform: open ? "rotate(180deg)" : "none",
              transition: reduced
                ? "none"
                : `transform 320ms ${EASE}, opacity 200ms`,
            }}
          />
        </button>
      </Arrive>
      <div
        id={listId}
        inert={!open}
        className="grid"
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          opacity: open ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 380ms ${EASE}, opacity ${open ? "280ms" : "140ms"} ${EASE}`,
        }}
      >
        <ul className="min-h-0 overflow-hidden pb-1 pl-[24px]">
          {task.steps.map((step, i) => {
            const last = i === task.steps.length - 1;
            const live = running && last;
            return (
              <li key={step.id} className="relative">
                <Arrive animate={mounted} reduced={reduced}>
                  {/* The trail: a thin line down from the task, branching to each step, the last one turning the corner. */}
                  <span
                    aria-hidden="true"
                    className="absolute -left-[16px] top-0 w-px bg-border"
                    style={last ? { height: 10 } : { bottom: 0 }}
                  />
                  <span
                    aria-hidden="true"
                    className={`absolute -left-[16px] top-[3px] h-[8px] w-[9px] border-b border-border ${last ? "rounded-bl-[5px] border-l" : ""}`}
                  />
                  <div className="flex min-h-[26px] flex-wrap items-center gap-x-1.5 gap-y-1 py-[3px] text-[12.5px] leading-5 text-muted-foreground">
                    <span className={live ? SHEEN : ""}>{step.text}</span>
                    {step.file && <FileChip name={step.file} />}
                    {step.detail && (
                      <span className="text-muted-foreground/70">
                        {step.detail}
                      </span>
                    )}
                  </div>
                </Arrive>
              </li>
            );
          })}
        </ul>
      </div>
    </li>
  );
}

export function TaskLog({
  tasks,
  onRerun,
  rerunLabel = "Run again",
  className = "",
  ...props
}: TaskLogProps) {
  const reduced = useReducedMotion();
  // Tasks and steps that exist on the first render just sit there; later ones arrive.
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setMounted(true));
    return () => cancelAnimationFrame(frame);
  }, []);
  const settled =
    tasks.length > 0 && tasks.every((t) => t.status !== "running");
  const live = tasks.find((t) => t.status === "running");
  const lastStep = live?.steps[live.steps.length - 1];

  return (
    <div className={`w-full ${className}`} {...props}>
      <ol className="space-y-1">
        {tasks.map((t) => (
          <Task
            key={t.id}
            task={t}
            animate={mounted}
            mounted={mounted}
            reduced={reduced}
          />
        ))}
      </ol>

      {onRerun && (
        <div
          className="grid"
          style={{
            gridTemplateRows: settled ? "1fr" : "0fr",
            opacity: settled ? 1 : 0,
            transition: reduced
              ? "none"
              : `grid-template-rows 380ms ${EASE}, opacity 300ms ${EASE}`,
          }}
        >
          <div className="min-h-0 overflow-hidden">
            <button
              type="button"
              inert={!settled}
              onClick={onRerun}
              className={`cursor-pointer mt-2.5 inline-flex h-8 items-center gap-1.5 rounded-lg px-3 text-[12.5px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
            >
              <RotateCcw
                aria-hidden="true"
                className="size-3.5 text-muted-foreground"
              />
              {rerunLabel}
            </button>
          </div>
        </div>
      )}

      <p role="status" aria-live="polite" className="sr-only">
        {live
          ? `${live.title}${lastStep ? `: ${lastStep.text}${lastStep.file ? ` ${lastStep.file}` : ""}` : ""}`
          : settled
            ? "All tasks finished"
            : ""}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

