import { TaskLog } from "@/components/task-log";

<TaskLog
  tasks={[
    { id: "find", title: "Finding project files", doneTitle: "Found project files", status: "done",
      steps: [{ id: "1", text: "Read", file: "page.tsx" }, { id: "2", text: "Scanning", detail: "52 files" }] },
  ]}
  onRerun={rerun}
/>
